use std::collections::{HashSet,VecDeque};impl Solution{pub fn remove_invalid_parentheses(s:String)->Vec<String>{fn ok(s:&str)->bool{let mut b=0;for c in s.chars(){if c=='(' {b+=1}else if c==')'{b-=1;if b<0{return false}}}b==0}let mut q=VecDeque::from([s.clone()]);let mut seen=HashSet::from([s]);let mut out=vec![];let mut found=false;while !q.is_empty()&&!found{let z=q.len();for _ in 0..z{let x=q.pop_front().unwrap();if ok(&x){out.push(x.clone());found=true;}if found{continue}for(i,c)in x.char_indices(){if c!='('&&c!=')'{continue}let mut y=x.clone();y.remove(i);if seen.insert(y.clone()){q.push_back(y)}}}}out}}
